import { useCallback } from 'react'
import { contactService } from '../../helpers/utility'
import { TELEPHONE_BLACK, EMAIL, WHATSAPP } from '../../images'
import { LANG_STRINGS } from '../../lang'
import ButtonWithIcon from '../ButtonWithIcon'
import { ContactCardStyle } from './index.style'

function ContactCard ({
  mobile, email, WAText, emailId, waId, mobileId, telephoneText
}) {
  const renderContactCard = useCallback((icon, title, id, data) => {
    return (
      <ButtonWithIcon
        text={title}
        id={id}
        className='contact-btn'
        gtmId='contact-card-gtm-id'
        icon={icon}
        onClick={() => contactService(data)}
      />
    )
  }, [])

  return (
    <ContactCardStyle align='center' justify='space-between'>
      {
        renderContactCard(
          TELEPHONE_BLACK, (telephoneText || LANG_STRINGS.telephone), mobileId,
          {
            type: 'mobile',
            mobile
          }
        )
      }
      {
        renderContactCard(
          EMAIL, LANG_STRINGS.email, emailId,
          {
            type: 'email',
            email
          }
        )
      }
      {
        renderContactCard(
          WHATSAPP, LANG_STRINGS.whatsApp, waId,
          {
            type: 'whatsapp',
            mobile,
            WAText
          }
        )
      }
    </ContactCardStyle>
  )
}

export default ContactCard
