import { useCallback } from 'react'
import { DisplayCircleIcon, DisplayFlexCCC, Row } from '../../../../../commonStyle/index.style'
import { Container, CustomText } from '../../../../../components'
import { BUSSINESS_MEN, INFO } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { RmDetailStyle } from './index.style'
import ContactCard from '../../../../../components/ContactCard'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { contactService } from '../../../../../helpers/utility'
import { useGlobalContextValue } from '../../../../../contextProvider/GlobalContext'
import { getCsDetailByAgentTag } from '../../../../../helpers/checkAgentTags'

function RmDetails () {
  const [{ getAgentDetailData = {} }] = useGlobalContextValue()
  const renderContactRow = useCallback((title, value, className, data) => {
    return (
      <Row align='center' justify='space-between' className={className}>
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          size='13px'
        >
          {title}
        </CustomText>
        <CustomText
          color={AgentColorPallette.black}
          weight={700}
          size='13px'
          onClick={() => contactService(data)}
        >
          {value}
        </CustomText>
      </Row>
    )
  }, [])

  return (
    <Container
      title={LANG_STRINGS.relationshipManager}
      backBtnId='back_rm_details'
      className='bg-white'
    >
      <RmDetailStyle>
        <div className='rm-detail-top-section'>
          <DisplayFlexCCC>
            <DisplayCircleIcon
              bgColor='transparent'
              width='80px'
              height='80px'
              className='rm-icon-circle'
            >
              <img src={BUSSINESS_MEN} alt='' className='rm-img' />
            </DisplayCircleIcon>
            <CustomText
              color={AgentColorPallette.darkCharcoal}
              size='18px'
              weight={700}
              top='10px'
              bottom='40px'
            >
              {getAgentDetailData?.tag_handler_details.name}
            </CustomText>
          </DisplayFlexCCC>
          <ContactCard
            mobile={getAgentDetailData?.tag_handler_details.phone_no}
            wa={getAgentDetailData?.tag_handler_details.phone_no}
            email={getAgentDetailData?.tag_handler_details.email}
            WAText={`hi ${getAgentDetailData?.tag_handler_details.name},\nsaya ${getAgentDetailData?.name}, salah satu mitra di PasarPolis ingin menanyakan terkait polis/aplikasi mitra`}
            mobileId='rm_phone_detail'
            waId='rm_wa_detail'
            emailId='rm_email_detail'
          />
        </div>
        <div className='rm-detail-bottom-section'>
          <CustomText
            color={AgentColorPallette.darkCharcoal}
            size='13px'
            weight={600}
          >
            {`Jika ${getAgentDetailData?.tag_handler_details.name} tidak dapat dihubungi, silakan menghubungi kami di:`}
          </CustomText>
          {
            renderContactRow(
              LANG_STRINGS.whatsApp,
              getCsDetailByAgentTag(getAgentDetailData).mobile,
              '',
              {
                type: 'whatsapp',
                mobile: getCsDetailByAgentTag(getAgentDetailData).wa,
                WAText: ''
              }
            )
          }
          {
            renderContactRow(
              LANG_STRINGS.email,
              getCsDetailByAgentTag(getAgentDetailData).email,
              'cs-contact-row',
              {
                type: 'email',
                email: getCsDetailByAgentTag(getAgentDetailData).email
              }
            )
          }
          <Row align='center'>
            <div className='service-info'>
              <DisplayCircleIcon className='info-icon-circle' bgColor={AgentColorPallette.black}>
                <img src={INFO} alt='' />
              </DisplayCircleIcon>
            </div>
            <CustomText
              color={AgentColorPallette.darkCharcoal}
            >
              {LANG_STRINGS.serviceHours}
            </CustomText>
          </Row>
        </div>
      </RmDetailStyle>
    </Container>
  )
}

export default RmDetails
